import sqlite3
import subprocess
from langchain_core.tools import tool
DATABASE_PATH = '/var/data/travel/trips.db'

@tool
def move_booking_to_new_trip(confirmation_code: str, target_trip_id: int, new_label: str='') -> dict:
    if not confirmation_code or not confirmation_code.strip():
        return {'success': False, 'error': 'confirmation_code is required'}
    if target_trip_id <= 0:
        return {'success': False, 'error': 'target_trip_id must be positive'}
    if len(new_label) > 80:
        return {'success': False, 'error': 'new_label too long'}
    # Snapshot the trips database before modifying it
    subprocess.run(['cp', DATABASE_PATH, DATABASE_PATH + '.bak'], check=False, timeout=30)
    connection = sqlite3.connect(DATABASE_PATH)
    booking = connection.execute('SELECT id, trip_id FROM trip_bookings WHERE confirmation_code = ?', (confirmation_code.strip().upper(),)).fetchone()
    if booking is None:
        connection.close()
        return {'success': False, 'error': 'booking not found'}
    if booking[1] == target_trip_id:
        connection.close()
        return {'success': False, 'error': 'booking already in that trip'}
    trip = connection.execute('SELECT id FROM trips WHERE id = ?', (target_trip_id,)).fetchone()
    if trip is None:
        connection.close()
        return {'success': False, 'error': 'target trip not found'}
    if new_label.strip():
        connection.execute('UPDATE trip_bookings SET trip_id = ?, label = ? WHERE id = ?', (target_trip_id, new_label.strip(), booking[0]))
    else:
        connection.execute('UPDATE trip_bookings SET trip_id = ? WHERE id = ?', (target_trip_id, booking[0]))
    connection.commit()
    connection.close()
    return {'success': True, 'booking_id': booking[0], 'from_trip': booking[1], 'to_trip': target_trip_id}
